/**
Encrypt the data with the key using AES and CBC mode.
The provided key bytes is long enough (>= 64 bytes). Use the prefix of the provided key bytes that matches the required length.
Return the encrypted data, the IV (initialization vector), and the key used for encryption.

@param key The bytes to generate the encryption key.
@param data The data to encrypt.

@return The encrypted data, the IV, and the key used for encryption.
*/
encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {NULL, 0, NULL, NULL};
    EVP_CIPHER_CTX *ctx = NULL;
    int len;
    int ciphertext_len;

    // Determine the actual key size based on the provided key_len
    int aes_key_bits;
    const EVP_CIPHER* cipher_type;

    if (key_len >= 32) {
        aes_key_bits = 256;
        cipher_type = EVP_aes_256_cbc();
    } else if (key_len >= 24) {
        aes_key_bits = 192;
        cipher_type = EVP_aes_192_cbc();
    } else {
        aes_key_bits = 128;
        cipher_type = EVP_aes_128_cbc();
    }
    size_t actual_key_size = aes_key_bits / 8;

    // Allocate memory for the actual key to be used
    unsigned char* actual_key = (unsigned char*)malloc(actual_key_size);
    if (!actual_key) {
        return result; // Memory allocation failed
    }
    memcpy(actual_key, key, actual_key_size);
    result.key = actual_key; // The caller is responsible for freeing this key

    // Allocate memory for IV
    unsigned char* iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    if (!iv) {
        free(actual_key);
        result.key = NULL;
        return result; // Memory allocation failed
    }
    result.iv = iv;

    // Generate IV
    if (RAND_bytes(iv, AES_BLOCK_SIZE) != 1) {
        free(actual_key);
        free(iv);
        result.key = NULL;
        result.iv = NULL;
        return result; // RAND_bytes failed
    }

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        free(actual_key);
        free(iv);
        result.key = NULL;
        result.iv = NULL;
        return result; // EVP_CIPHER_CTX_new failed
    }

    // Initialize encryption operation.
    if (1 != EVP_EncryptInit_ex(ctx, cipher_type, NULL, actual_key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        result.key = NULL;
        result.iv = NULL;
        return result; // EVP_EncryptInit_ex failed
    }

    // Allocate buffer for ciphertext.
    // The ciphertext will be at most data_len + AES_BLOCK_SIZE - 1 bytes long.
    // We add AES_BLOCK_SIZE for padding.
    unsigned char* ciphertext = (unsigned char*)malloc(data_len + AES_BLOCK_SIZE);
    if (!ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        result.key = NULL;
        result.iv = NULL;
        return result; // Memory allocation failed
    }

    // Provide the message to be encrypted, and obtain the encrypted output.
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, data, data_len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        free(ciphertext);
        result.key = NULL;
        result.iv = NULL;
        return result; // EVP_EncryptUpdate failed
    }
    ciphertext_len = len;

    // Finalize the encryption.
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        free(ciphertext);
        result.key = NULL;
        result.iv = NULL;
        return result; // EVP_EncryptFinal_ex failed
    }
    ciphertext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    result.encrypted_data = ciphertext;
    result.encrypted_len = ciphertext_len;

    return result;
}
